CREATE OR REPLACE FUNCTION public.set_capital_only_recovery(p_loan_id uuid, p_enabled boolean, p_operator_id uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$ DECLARE v_contract public.contratos%ROWTYPE; v_owner_id uuid; v_actor_id uuid; v_auth_uid uuid := auth.uid(); v_current boolean; v_changed boolean; v_notes text; v_backup jsonb; BEGIN IF p_loan_id IS NULL OR p_enabled IS NULL THEN RAISE EXCEPTION 'Contrato e estado obrigatorios.'; END IF; SELECT * INTO v_contract FROM public.contratos WHERE id = p_loan_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Contrato nao encontrado.'; END IF; v_owner_id := coalesce(v_contract.profile_id, v_contract.owner_id); IF v_auth_uid IS NULL THEN RAISE EXCEPTION 'Sessao autenticada obrigatoria.'; END IF; SELECT caller.id INTO v_actor_id FROM public.perfis caller LEFT JOIN public.perfis owner ON owner.id = v_owner_id WHERE caller.user_id = v_auth_uid AND (caller.id = v_owner_id OR caller.supervisor_id = v_owner_id OR caller.owner_profile_id = v_owner_id OR owner.supervisor_id = caller.id OR owner.owner_profile_id = caller.id) LIMIT 1; IF v_actor_id IS NULL THEN RAISE EXCEPTION 'Acesso negado.'; END IF; v_current := coalesce(v_contract.capital_only_recovery, false); v_changed := v_current IS DISTINCT FROM p_enabled; v_backup := coalesce(v_contract.capital_only_recovery_policy, v_contract.policies_snapshot, jsonb_build_object('interestRate', coalesce(v_contract.interest_rate,0), 'finePercent', coalesce(v_contract.fine_percent,0), 'dailyInterestPercent', coalesce(v_contract.daily_interest_percent,0))); IF p_enabled THEN v_notes := coalesce(v_contract.notes,''); IF position('[CAPITAL_ONLY_RECOVERY]' in v_notes) = 0 THEN v_notes := concat_ws(E'\n', nullif(btrim(v_notes),''), '[CAPITAL_ONLY_RECOVERY] Somente capital: recuperar apenas o principal, sem juros ou encargos.'); END IF; UPDATE public.contratos SET capital_only_recovery=true, capital_only_recovery_policy=v_backup, capital_only_recovery_updated_at=now(), capital_only_recovery_updated_by=v_actor_id, notes=v_notes, interest_rate=0, fine_percent=0, daily_interest_percent=0 WHERE id=p_loan_id; UPDATE public.parcelas SET interest_remaining=0, late_fee_accrued=0, scheduled_interest=0 WHERE loan_id=p_loan_id AND upper(coalesce(status,'')) NOT IN ('RENEGOCIADO','CANCELADO','PAID','PAGO','QUITADO','QUITADA','FINALIZADO'); ELSE SELECT coalesce(string_agg(line,E'\n' ORDER BY ord),'') INTO v_notes FROM unnest(string_to_array(coalesce(v_contract.notes,''),E'\n')) WITH ORDINALITY AS x(line,ord) WHERE position('[CAPITAL_ONLY_RECOVERY]' in line)=0; UPDATE public.contratos SET capital_only_recovery=false, capital_only_recovery_policy=v_backup, capital_only_recovery_updated_at=now(), capital_only_recovery_updated_by=v_actor_id, notes=nullif(btrim(v_notes),''), interest_rate=coalesce(case when coalesce(v_backup->>'interestRate','') ~ '^-?[0-9]+([.][0-9]+)?$' then (v_backup->>'interestRate')::numeric end, interest_rate), fine_percent=coalesce(case when coalesce(v_backup->>'finePercent','') ~ '^-?[0-9]+([.][0-9]+)?$' then (v_backup->>'finePercent')::numeric end, fine_percent), daily_interest_percent=coalesce(case when coalesce(v_backup->>'dailyInterestPercent','') ~ '^-?[0-9]+([.][0-9]+)?$' then (v_backup->>'dailyInterestPercent')::numeric end, daily_interest_percent) WHERE id=p_loan_id; END IF; IF v_changed THEN INSERT INTO public.transacoes(id,profile_id,loan_id,date,type,amount,principal_delta,interest_delta,late_fee_delta,category,notes,operator_id,meta,created_at) VALUES(gen_random_uuid(),v_owner_id,p_loan_id,now(),case when p_enabled then 'CAPITAL_ONLY_RECOVERY_ENABLED' else 'CAPITAL_ONLY_RECOVERY_DISABLED' end,0,0,0,0,'INFO',case when p_enabled then 'Contrato marcado como Somente Capital. Recebimentos futuros recuperam apenas o principal.' else 'Marcacao Somente Capital removida com confirmacao do operador.' end,v_actor_id,jsonb_build_object('previous_state',v_current,'new_state',p_enabled,'changed_at',now()),now()); END IF; RETURN jsonb_build_object('ok',true,'changed',v_changed,'enabled',p_enabled,'operator_id',v_actor_id); END; $$; REVOKE ALL ON FUNCTION public.set_capital_only_recovery(uuid, boolean, uuid) FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION public.set_capital_only_recovery(uuid, boolean, uuid) TO authenticated;;
